-- Round 2. Existing IDs, private missions, reflections and revision guards survive.
alter table public.profiles add column joined_at timestamptz not null default now();
update public.profiles p set joined_at=u.created_at from auth.users u where u.id=p.id;
alter table public.profiles add column baseline_answers jsonb;
alter table public.missions add column interests text[] not null default '{}';
alter table public.missions add column places text[] not null default '{}';
alter table public.missions add column ladder text not null default '';
alter table public.missions add column level text not null default 'easy' check(level in ('easy','normal','stretch'));
alter table public.missions add column type text not null default 'do' check(type in ('do','learn'));
alter table public.missions add column active boolean not null default true;
alter table public.missions drop constraint missions_minutes_check;
alter table public.missions add constraint missions_minutes_check check(minutes between 1 and 1440);
update public.missions set interests=quick_picks,level=case size when 'Normal' then 'normal' when 'Stretch' then 'stretch' else 'easy' end;
-- Keep old mission rows as inactive history, never in the new recommendation pool.
update public.missions set active=false where user_id is null;
alter table public.missions drop column area;
alter table public.priority_words drop column priority_group;
alter table public.quick_pick_cards drop column domain;

-- A single, one-time state conversion. Old Want to try is now From time to time.
update public.journey_entries set entry=jsonb_set(entry,'{state}',to_jsonb(case
 when entry->>'state' in ('tried','want_to_try') then 'from_time_to_time'
 when entry->>'state' in ('love','into_it') then 'into_it'
 when entry->>'state' in ('craft','all_in') then 'all_in'
 when entry->>'state' in ('ember','paused','on_pause') then 'on_pause'
 else 'want_to_try' end)) where kind='interest';
update public.journey_entries set entry=jsonb_set(entry,'{meta}',coalesce(entry->'meta','{}')-array['planet','priority_group','planet_notes','focus_area','orbit'])
 where entry->'meta' ?| array['planet','priority_group','planet_notes','focus_area','orbit'];
drop view public.priorities;
create view public.priorities with(security_invoker=true) as
 select id,user_id,entry->>'title' name,case when entry->>'state' in ('let_go','released') then 'let_go'
 when entry->>'state' in ('mine','important') or kind='strength' then 'important' else 'working_on' end state,
 entry->>'source' source,revision from public.journey_entries where kind in ('value','strength');
create or replace view public.user_interests with(security_invoker=true) as
 select e.id,e.user_id,e.entry->>'title' interest,
 case e.entry->>'state' when 'all_in' then 'All in' when 'into_it' then 'Into it' when 'from_time_to_time' then 'From time to time' when 'on_pause' then 'On pause' else 'Want to try' end stage,
 least(5,greatest(1,coalesce((select max(i.mission_step)+1 from public.intentions i join public.check_ins c on c.intention_id=i.id and c.user_id=i.user_id where i.interest_id=e.id and i.user_id=e.user_id and c.outcome='yes' and i.mission_id is not null),1))) current_ladder_step,
 e.entry->>'state'='on_pause' paused,
 (select max(i.day) from public.intentions i join public.check_ins c on c.intention_id=i.id and c.user_id=i.user_id where i.interest_id=e.id and i.user_id=e.user_id and c.outcome='yes') last_activity_date
 from public.journey_entries e where e.kind='interest';
revoke all on public.priorities from public,anon;
grant select on public.priorities to authenticated,service_role;

create table public.places(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,label text not null check(char_length(label) between 1 and 120),sort_order integer not null default 0,created_at timestamptz not null default now(),unique(user_id,label));
create table public.interest_links(interest text not null,similar_interest text not null,reason text not null,primary key(interest,similar_interest));
create table public.learning_shelf(id text primary key,title text not null,author text not null,priorities text[] not null default '{}',interests text[] not null default '{}',why_it_fits text not null);
create table public.someday_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,text text not null check(char_length(text) between 1 and 500),horizon text not null check(horizon in ('this_year','five_years','ten_years','later_in_life')),status text not null default 'open' check(status in ('open','lived','let_go')),priority text,interest text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),revision integer not null default 1);
create trigger zz_someday_revision before update on public.someday_items for each row execute function public.advance_practice_revision();
create table public.chloe_moments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null check(type in ('narrowing','all_in_check','worst_case','cost_of_waiting','people_question','stretch_nudge','learning','someday_link','seasonal_look_back')),session_id text not null check(char_length(session_id) between 1 and 100),payload jsonb,asked_at timestamptz not null default now(),unique(user_id,session_id));
create index chloe_moments_recent on public.chloe_moments(user_id,type,asked_at desc);
create table public.checkin_summaries(user_id uuid not null references auth.users(id) on delete cascade,day date not null,session_id text not null,hard_day boolean not null default false,summary text not null default '',source_signature text,opener_line jsonb,created_at timestamptz not null default now(),primary key(user_id,day));

alter table public.places enable row level security;
alter table public.interest_links enable row level security;
alter table public.learning_shelf enable row level security;
alter table public.someday_items enable row level security;
alter table public.chloe_moments enable row level security;
alter table public.checkin_summaries enable row level security;
revoke all on public.places,public.interest_links,public.learning_shelf,public.someday_items,public.chloe_moments,public.checkin_summaries from public,anon,authenticated;
grant select,insert,update,delete on public.places,public.someday_items to authenticated;
grant select on public.interest_links,public.learning_shelf,public.chloe_moments,public.checkin_summaries to authenticated;
grant all on public.places,public.interest_links,public.learning_shelf,public.someday_items,public.chloe_moments,public.checkin_summaries to service_role;
create policy places_owner on public.places for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy someday_owner on public.someday_items for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy links_reader on public.interest_links for select to authenticated using(true);
create policy shelf_reader on public.learning_shelf for select to authenticated using(true);
create policy moments_reader on public.chloe_moments for select to authenticated using((select auth.uid())=user_id);
create policy summaries_reader on public.checkin_summaries for select to authenticated using((select auth.uid())=user_id);

alter table public.intentions add column source text not null default 'typed' check(source in ('typed','suggested'));
alter table public.intentions add column level text check(level in ('easy','normal','stretch'));
alter table public.intentions add column type text not null default 'do' check(type in ('do','learn'));
alter table public.intentions add column someday_item_id uuid references public.someday_items(id) on delete set null;
-- Existing reflected rows are immutable; infer their source at read time if needed.
update public.intentions i set source='suggested',level=m.level,type=m.type from public.missions m where i.mission_id=m.id and not exists(select 1 from public.check_ins c where c.intention_id=i.id);
create or replace function public.validate_mission_link() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if new.mission_id is not null and not exists(select 1 from public.missions m where m.id=new.mission_id and m.ladder_step=new.mission_step and (m.user_id is null or m.user_id=new.user_id)) then raise exception 'Choose a mission from your own library.' using errcode='23514'; end if;
 if new.someday_item_id is not null and not exists(select 1 from public.someday_items s where s.id=new.someday_item_id and s.user_id=new.user_id) then raise exception 'Choose your own someday item.' using errcode='23514'; end if;
 if new.source='typed' and new.mission_id is not null then new.source:='suggested'; end if;
 if new.for_me and new.for_whom<>'' then raise exception 'Choose one beneficiary.' using errcode='23514'; end if;
 return new;
end;$$;
create view public.daily_focus with(security_invoker=true) as select i.id,i.user_id,i.day date,i.source,i.action text,i.when_context plan,i.value priority,i.place,i.interest,i.mission_id,i.level,i.type,i.someday_item_id,c.outcome status,c.energy from public.intentions i left join public.check_ins c on c.intention_id=i.id and c.user_id=i.user_id;
revoke all on public.daily_focus from public,anon;
grant select on public.daily_focus to authenticated,service_role;
create or replace function public.mission_options(p_tag text,p_step integer) returns setof public.missions language sql stable security invoker set search_path='' as $$
 select * from public.missions where active and ladder_step=p_step and (interests @> array[p_tag] or priorities @> array[p_tag] or places @> array[p_tag] or tags @> array[p_tag]) order by id;
$$;

-- Server-only reservation; advisory lock serializes all moment types for an owner.
create function public.reserve_chloe_moment(p_user_id uuid,p_type text,p_session text) returns jsonb language plpgsql security invoker set search_path='' as $$
declare result jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
 if exists(select 1 from public.chloe_moments where user_id=p_user_id and (session_id=p_session or (type=p_type and asked_at>now()-interval '7 days'))) then return null; end if;
 insert into public.chloe_moments(user_id,type,session_id) values(p_user_id,p_type,p_session) returning to_jsonb(chloe_moments.*) into result;
 return result;
end;$$;
revoke execute on function public.reserve_chloe_moment(uuid,text,text) from public,anon,authenticated;
grant execute on function public.reserve_chloe_moment(uuid,text,text) to service_role;

-- Replacing today's already-reflected focus preserves its full story in an event.
-- Expected revision prevents a stale device from archiving a newer focus.
create function public.replace_daily_focus(p_id uuid,p_revision integer,p_focus jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare focus public.intentions; reflection public.check_ins; event_id uuid:=gen_random_uuid(); replacement public.intentions;
begin
 select * into focus from public.intentions where id=p_id and user_id=(select auth.uid()) and revision=p_revision for update;
 if focus.id is null then raise exception 'Your focus changed. Reload before replacing it.' using errcode='40001'; end if;
 if focus.day<>(now() at time zone (select timezone from public.profiles where id=auth.uid()))::date then raise exception 'Only today can be replaced.'; end if;
 select * into reflection from public.check_ins where intention_id=focus.id and user_id=auth.uid();
 if reflection.intention_id is not null then
   insert into public.journey_entries(id,user_id,kind,entry) values(event_id,auth.uid(),'event',jsonb_build_object('id',event_id,'kind','event','title',focus.action,'body',reflection.reflection,'state','replaced','source','Earlier focus','source_ids',jsonb_build_array(focus.id),'created_at',now(),'updated_at',now(),'meta',jsonb_build_object('focus',to_jsonb(focus),'reflection',to_jsonb(reflection))));
   delete from public.check_ins where intention_id=focus.id and user_id=auth.uid();
 end if;
 replacement:=jsonb_populate_record(focus,p_focus);
 update public.intentions set action=replacement.action,value=replacement.value,person=replacement.person,interest=replacement.interest,interest_id=replacement.interest_id,value_id=replacement.value_id,source=replacement.source,level=replacement.level,type=replacement.type,mission_id=replacement.mission_id,mission_step=replacement.mission_step,someday_item_id=replacement.someday_item_id,place=replacement.place,when_context=replacement.when_context,for_me=replacement.for_me,for_whom=replacement.for_whom where id=focus.id returning * into replacement;
 return to_jsonb(replacement);
end;$$;
revoke execute on function public.replace_daily_focus(uuid,integer,jsonb) from public,anon;
grant execute on function public.replace_daily_focus(uuid,integer,jsonb) to authenticated;

