"],"places":["for myself","at home"],"ladder_step":4,"stage":"Into it","size":"Normal","level":"normal","minutes":30,"cost":"$","setting":"Home","safety_note":"","interests":["working out"],"quick_picks":["working out"],"priorities":["healthy","energetic","independent"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"GR-FIT-4c","mission_text":"Host the first garage workout with your neighbors and the trainer. Put on music and have water ready.","first_step":"Confirm the time with the trainer and the group.","ladder":"Getting fit","tags":["fitness","neighbors","trainer","hosting"],"who_for":["community"],"places":["in my community","at home"],"ladder_step":4,"stage":"Into it","size":"Stretch","level":"stretch","minutes":60,"cost":"$$","setting":"Home","safety_note":"Confirm the trainer is certified and insured, and clear the space of trip hazards. Check with your doctor first if you're new to exercise or have health concerns.","interests":["working out"],"quick_picks":["working out"],"priorities":["healthy","energetic","part of a community","a leader"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"GR-FIT-5a","mission_text":"Invite one more neighbor to join your group workout.","first_step":"Think of who has said \"I should really get back into it.\"","ladder":"Getting fit","tags":["fitness","neighbors","invite"],"who_for":["community"],"places":["in my community"],"ladder_step":5,"stage":"All in","size":"5-minute","level":"easy","minutes":5,"cost":"Free","setting":"Phone","safety_note":"","interests":["working out"],"quick_picks":["working out"],"priorities":["healthy","energetic","part of a community"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"GR-FIT-5b","mission_text":"Work out with your kid, partner or parent today. Let them pick the activity.","first_step":"Ask: \"Want to move with me today? You pick.\"","ladder":"Getting fit","tags":["fitness","family","together"],"who_for":["partner"],"places":["with my partner"],"ladder_step":5,"stage":"All in","size":"Normal","level":"normal","minutes":30,"cost":"Free","setting":"Anywhere","safety_note":"","interests":["working out"],"quick_picks":["working out"],"priorities":["healthy","energetic","there for family"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"GR-FIT-5c","mission_text":"Sign up for an event that gives your training a goal (a 5K, charity walk, obstacle race, ride) and ask someone to do it with you.","first_step":"Search for an event six to ten weeks out.","ladder":"Getting fit","tags":["fitness","event","goal","together"],"who_for":["friend"],"places":["with friends"],"ladder_step":5,"stage":"All in","size":"Stretch","level":"stretch","minutes":45,"cost":"$$","setting":"Online","safety_note":"Build up gradually over the weeks before the event. Check with your doctor first if you're new to exercise or have health concerns.","interests":["working out"],"quick_picks":["working out"],"priorities":["healthy","energetic","ambitious"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-1a","mission_text":"Pick the one moment today where you usually rush or snap (school run, traffic, a slow reply) and decide now how you'll handle it.","first_step":"Name the moment in one line: \"When ___ happens, I'll ___.\"","ladder":"Patience","tags":["patience","planning","trigger"],"who_for":["self"],"places":["for myself"],"ladder_step":1,"stage":"Want to try","size":"5-minute","level":"easy","minutes":5,"cost":"Free","setting":"Anywhere","safety_note":"","interests":[],"quick_picks":[],"priorities":["patient","calm","a clear thinker"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-1b","mission_text":"Let someone finish every sentence today without jumping in, especially your kid or partner.","first_step":"Choose the conversation you'll practice in first.","ladder":"Patience","tags":["patience","listening"],"who_for":["partner"],"places":["with my partner"],"ladder_step":1,"stage":"Want to try","size":"Normal","level":"normal","minutes":15,"cost":"Free","setting":"Anywhere","safety_note":"","interests":[],"quick_picks":[],"priorities":["patient","calm","respectful"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-1c","mission_text":"Do one slow thing on purpose: cook from scratch, do a puzzle, or take the long walk without checking the time.","first_step":"Pick the slow thing and put your phone in a drawer.","ladder":"Patience","tags":["patience","slow down","no phone"],"who_for":["self"],"places":["for myself","at home"],"ladder_step":1,"stage":"Want to try","size":"Stretch","level":"stretch","minutes":60,"cost":"Free","setting":"Home","safety_note":"","interests":["cooking for friends"],"quick_picks":["cooking for friends"],"priorities":["patient","calm","free"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-2a","mission_text":"When you feel the rush today, take three slow breaths before you say anything.","first_step":"Set a phone reminder labeled \"three breaths\" for your busiest hour.","ladder":"Patience","tags":["patience","breathing","pause"],"who_for":["self"],"places":["for myself"],"ladder_step":2,"stage":"From time to time","size":"5-minute","level":"easy","minutes":5,"cost":"Free","setting":"Anywhere","safety_note":"","interests":["meditating"],"quick_picks":["meditating"],"priorities":["patient","calm"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-2b","mission_text":"Teach someone a thing you're good at and let them go at their own pace, even if you could do it faster.","first_step":"Offer: \"Want me to show you how?\"","ladder":"Patience","tags":["patience","teaching"],"who_for":["kid"],"places":["with my kids","at home"],"ladder_step":2,"stage":"From time to time","size":"Normal","level":"normal","minutes":20,"cost":"Free","setting":"Home","safety_note":"","interests":[],"quick_picks":[],"priorities":["patient","calm","respectful"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-2c","mission_text":"Pick the line, the slow lane or the longer route today and use the time to call or think about someone you love.","first_step":"Decide where you'll choose the slow option.","ladder":"Patience","tags":["patience","waiting","reframe"],"who_for":["parent"],"places":["with my parents"],"ladder_step":2,"stage":"From time to time","size":"Stretch","level":"stretch","minutes":45,"cost":"Free","setting":"Out and about","safety_note":"","interests":[],"quick_picks":[],"priorities":["patient","calm"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-3a","mission_text":"Before you reply to the message that annoyed you, wait an hour. Then reply kindly.","first_step":"Mark it unread and set a reminder.","ladder":"Patience","tags":["patience","communication","work"],"who_for":["colleague"],"places":["with my team"],"ladder_step":3,"stage":"Into it","size":"5-minute","level":"easy","minutes":5,"cost":"Free","setting":"Phone","safety_note":"","interests":[],"quick_picks":[],"priorities":["patient","calm","respectful"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-3b","mission_text":"Ask someone who tests your patience one real question about their day, and listen to the whole answer.","first_step":"Pick the person and the moment.","ladder":"Patience","tags":["patience","empathy","listening"],"who_for":["colleague"],"places":["with my team","at work","at school"],"ladder_step":3,"stage":"Into it","size":"Normal","level":"normal","minutes":15,"cost":"Free","setting":"Work or school","safety_note":"","interests":[],"quick_picks":[],"priorities":["patient","calm","respectful"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-3c","mission_text":"Start something that can't be rushed: plant seeds, start sourdough, begin a long book, learn a slow song.","first_step":"Pick the thing and get what you need today.","ladder":"Patience","tags":["patience","long game","new start"],"who_for":["self"],"places":["for myself","at home"],"ladder_step":3,"stage":"Into it","size":"Stretch","level":"stretch","minutes":45,"cost":"$","setting":"Home","safety_note":"","interests":["reading","gardening"],"quick_picks":["reading","gardening"],"priorities":["patient","calm","persistent"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-4a","mission_text":"Tell someone you were short with that you're sorry, in one sentence, no excuses.","first_step":"Write it before you say it.","ladder":"Patience","tags":["patience","repair","apology"],"who_for":["kid"],"places":["with my kids","at home"],"ladder_step":4,"stage":"Into it","size":"5-minute","level":"easy","minutes":5,"cost":"Free","setting":"Home","safety_note":"","interests":[],"quick_picks":[],"priorities":["patient","calm","forgiving","humble"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-4b","mission_text":"Notice when you were patient today and what it made possible. Tell the person what you appreciated about the moment.","first_step":"Think of one moment from today that went better because you waited.","ladder":"Patience","tags":["patience","noticing","appreciation"],"who_for":["partner"],"places":["with my partner"],"ladder_step":4,"stage":"Into it","size":"Normal","level":"normal","minutes":10,"cost":"Free","setting":"Anywhere","safety_note":"","interests":[],"quick_picks":[],"priorities":["patient","calm","grateful"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-4c","mission_text":"Spend an afternoon with someone who moves slower than you (a grandparent, a toddler, a new learner) at their pace.","first_step":"Call to set a time.","ladder":"Patience","tags":["patience","presence","generations"],"who_for":["parent"],"places":["with my parents"],"ladder_step":4,"stage":"Into it","size":"Stretch","level":"stretch","minutes":120,"cost":"Free","setting":"Anywhere","safety_note":"","interests":[],"quick_picks":[],"priorities":["patient","calm","there for family","respectful"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-5a","mission_text":"Text someone in a stressful wait (results, a job, a decision): \"Thinking of you. No need to reply.\"","first_step":"Think of who's waiting on something right now.","ladder":"Patience","tags":["patience","support"],"who_for":["friend"],"places":["with friends"],"ladder_step":5,"stage":"All in","size":"5-minute","level":"easy","minutes":5,"cost":"Free","setting":"Phone","safety_note":"","interests":[],"quick_picks":[],"priorities":["patient","calm","loyal"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-5b","mission_text":"Help someone else stay calm in a hard moment today: a kid's meltdown, a coworker's deadline, a friend's bad news. Lower your voice and slow down.","first_step":"Decide where you're most likely to need it.","ladder":"Patience","tags":["patience","calm","support"],"who_for":["kid"],"places":["with my kids"],"ladder_step":5,"stage":"All in","size":"Normal","level":"normal","minutes":15,"cost":"Free","setting":"Anywhere","safety_note":"","interests":[],"quick_picks":[],"priorities":["patient","calm","of service"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"BE-PAT-5c","mission_text":"Coach or tutor someone for an hour on something they find hard, and celebrate one small win with them.","first_step":"Offer one hour this week to a kid, coworker or neighbor.","ladder":"Patience","tags":["patience","coaching","teaching"],"who_for":["community"],"places":["in my community"],"ladder_