3a","mission_text":"Ask your partner, \"Is there anything I could do this week to make your life easier?\" and do the thing.","first_step":"Pick a calm moment to ask.","ladder":"Partner","tags":["partner","care","listening"],"who_for":["partner"],"places":["with my partner"],"ladder_step":3,"stage":"Into it","size":"5-minute","level":"easy","minutes":5,"cost":"Free","setting":"Anywhere","safety_note":"","interests":[],"quick_picks":[],"priorities":["loving","there for family","kind"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"PE-PAR-3b","mission_text":"Take a 30-minute walk together and talk about something other than work, kids or the house.","first_step":"Suggest it right after dinner.","ladder":"Partner","tags":["partner","walking","conversation"],"who_for":["partner"],"places":["with my partner","outdoors"],"ladder_step":3,"stage":"Into it","size":"Normal","level":"normal","minutes":30,"cost":"Free","setting":"Outdoors","safety_note":"","interests":[],"quick_picks":[],"priorities":["loving","there for family","healthy"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"PE-PAR-3c","mission_text":"Ask your partner what they're dreaming about for the next year and how you can help them get there.","first_step":"Bring it up on a walk or a drive, not during chores.","ladder":"Partner","tags":["partner","dreams","future"],"who_for":["partner"],"places":["with my partner"],"ladder_step":3,"stage":"Into it","size":"Stretch","level":"stretch","minutes":60,"cost":"Free","setting":"Anywhere","safety_note":"","interests":[],"quick_picks":[],"priorities":["loving","there for family","hopeful"],"type":"do","active":true,"provenance":"Kelly · Round 2 · 14 November 2026"},{"id":"PE-PAR-4a","mission_text":"Leave a handwritten note where your partner will find it tomorrow morning.","first_step":"Grab a sticky note and a pen.","ladder":"Partner","tags":["partner","note","surprise"],"who_for":["partner"],"pl