update round2_missions n set id=o.id from public.missions o where o.user_id is null and o.mission_text=n.mission_text and o.size=n.size;
insert into public.missions(id,mission_text,first_step,ladder,tags,who_for,places,ladder_step,stage,size,level,minutes,cost,setting,safety_note,interests,quick_picks,priorities,type,active,provenance) select id,mission_text,first_step,ladder,tags,who_for,places,ladder_step,stage,size,level,minutes,cost,setting,safety_note,interests,quick_picks,priorities,type,active,provenance from round2_missions on conflict(id) do update set mission_text=excluded.mission_text,first_step=excluded.first_step,ladder=excluded.ladder,tags=excluded.tags,who_for=excluded.who_for,places=excluded.places,ladder_step=excluded.ladder_step,stage=excluded.stage,size=excluded.size,level=excluded.level,minutes=excluded.minutes,cost=excluded.cost,setting=excluded.setting,safety_note=excluded.safety_note,interests=excluded.interests,quick_picks=excluded.quick_picks,priorities=excluded.priorities,type=excluded.type,active=excluded.active,provenance=excluded.provenance;
drop table round2_missions;
insert into public.interest_links(interest,similar_interest,reason) select interest,similar_interest,reason from jsonb_populate_recordset(null::public.interest_links,$seed$[{"interest":"cooking for friends","similar_interest":"baking","reason":"Slow, hands-on cooking you can share."},{"interest":"cooking for friends","similar_interest":"hosting game night","reason":"Another easy reason to have people over."},{"interest":"cooking for friends","similar_interest":"gardening","reason":"Grow what you cook."},{"interest":"exploring new places","similar_interest":"hiking","reason":"New places on foot."},{"interest":"exploring new places","similar_interest":"taking photos","reason":"See new places more closely."},{"interest":"exploring new places","similar_interest":"camping","reason":"Stay the night somewhere new."},{"interest":"hiking","similar_interest":"camping","reason":"A night outside after the hike."},{"interest":"hiking","similar_interest":"birdwatching","reason":"Slow down and notice what lives there."},{"interest":"hiking","similar_interest":"running","reason":"The same trails, a bit faster."},{"interest":"reading","similar_interest":"a book club","reason":"Reading with company."},{"interest":"reading","similar_interest":"journaling","reason":"From reading words to writing your own."},{"interest":"reading","similar_interest":"learning a language","reason":"Read in a new language."},{"interest":"volunteering","similar_interest":"mentoring someone","reason":"Giving time one-on-one."},{"interest":"volunteering","similar_interest":"gardening","reason":"Help a community garden grow."},{"interest":"volunteering","similar_interest":"cooking for friends","reason":"Cook for someone who needs it."},{"interest":"building things","similar_interest":"sketching","reason":"Draw it before you build it."},{"interest":"building things","similar_interest":"gardening","reason":"Build a planter, then fill it."},{"interest":"playing sports","similar_interest":"pickleball","reason":"Qu