insert into public.learning_shelf(id,title,author,priorities,interests,why_it_fits) select id,title,author,priorities,interests,why_it_fits from jsonb_populate_recordset(null::public.learning_shelf,$seed$[{"id":"book-01","title":"The Power of Kindness","author":"Piero Ferrucci","priorities":["kind"],"interests":[],"why_it_fits":"Why kindness is a strength, with small everyday ways to practice it."},{"id":"book-02","title":"Wonder","author":"R. J. Palacio","priorities":["kind","brave"],"interests":[],"why_it_fits":"A short novel about choosing kindness, for readers who prefer stories."},{"id":"book-03","title":"The 5 Love Languages","author":"Gary Chapman","priorities":["loving","there for family"],"interests":[],"why_it_fits":"Helps you show love in the way the people close to you actually feel it."},{"id":"book-04","title":"Together","author":"Vivek H. Murthy","priorities":["a good friend","part of a community"],"interests":[],"why_it_fits":"On loneliness and why connection matters, with simple ways to build it."},{"id":"book-05","title":"How to Win Friends and Influence People","author":"Dale Carnegie","priorities":["good with people","a good friend"],"interests":[],"why_it_fits":"Classic, practical habits for warmth and getting along."},{"id":"book-06","title":"The Speed of Trust","author":"Stephen M. R. Covey","priorities":["loyal","honest"],"interests":[],"why_it_fits":"How trust is built and kept, at home and at work."},{"id":"book-07","title":"Crucial Conversations","author":"Kerry Patterson, Joseph Grenny, Ron McMillan, Al Switzler","priorities":["respectful","honest","calm"],"interests":[],"why_it_fits":"How to talk about hard things with respect when emotions run high."},{"id":"book-08","title":"Justice: What’s the Right Thing to Do?","author":"Michael J. Sandel","priorities":["fair","a clear thinker"],"interests":[],"why_it_fits":"Clear, lively thinking about fairness and hard choices."},{"id":"book-09","title":"The Five Dysfunctions of a Team","author":"